package iotest

import (
	"bytes"
	"io"
	"testing"
)

func TestTruncateWriter(t *testing.T) {
	var buf bytes.Buffer
	w := TruncateWriter(&buf, 10)
	w.Write([]byte("abcdefgh"))
	if buf.Len() != 10 {
		t.Errorf("buf: %d, want 10", buf.Len())
	}
	w.Write([]byte("ijklmn"))
	if buf.Len() != 10 {
		t.Errorf("buf: %d, want 10", buf.Len())
	}
}

func TestTruncateWriterError(t *testing.T) {
	var buf bytes.Buffer
	w := TruncateWriter(&buf, -1)
	if _, err := w.Write([]byte("abcdefgh")); err == nil {
		t.Error("expected error")
	}
	if buf.Len() != 0 {
		t.Errorf("buf: %d, want 0", buf.Len())
	}
}

